<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>苍玄界 - 最终定稿版(双端兼容)</title>
    <!-- 字体与图标 -->
    <link href="https://cdn.bootcdn.net/ajax/libs/font-awesome/6.4.2/css/all.min.css" rel="stylesheet">
    <link href="https://fonts.googleapis.com/css2?family=Zhi+Mang+Xing&family=Noto+Serif+SC:wght@400;700;900&display=swap" rel="stylesheet">
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>

    <style>
        /* ================= 全局变量 ================= */
        :root {
            --cx-bg-base: #030712;
            --cx-gold-light: #fef08a;
            --cx-gold-main: #d97706;
            --cx-gold-dark: #92400e;
            --cx-text-title: #f8fafc;
            --cx-text-body: #cbd5e1;
            --cx-text-muted: #64748b;
            --cx-danger: #ef4444;
            --cx-glass-border: rgba(217, 119, 6, 0.35);
        }

        * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; }

        body {
            margin: 0;
            font-family: 'Noto Serif SC', serif;
            display: flex;
            justify-content: center;
            align-items: center;
            background: transparent;
        }

        /* ================= 容器基础 ================= */
        .cx-wrapper-reset {
            width: 100%;
            max-width: 1200px;
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .cx-launcher {
            position: relative;
            width: 100%;
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 15px 40px rgba(0,0,0,0.8), inset 0 0 0 1px rgba(217, 119, 6, 0.15);
            font-size: 16px;
        }

        /* 核心底图 */
        .cx-base-bg-img {
            display: block;
            width: 100%;
            height: auto;
            pointer-events: none;
            transition: all 0.3s;
        }

        /* UI层绝对定位，覆盖在底图上 */
        .ui-layer {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            z-index: 10;
        }

        .view-container {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            display: none;
            z-index: 10;
        }

        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-thumb { background: var(--cx-gold-dark); border-radius: 2px; }

        /* 防止图标拦截点击 */
        button i, .cx-music-btn i, .cx-btn-icon i, .cx-nav-btn i { pointer-events: none; }

        /* ================= BGM 菜单 ================= */
        .cx-music-wrapper { position: absolute; top: 20px; right: 20px; z-index: 999; }
        .cx-music-btn {
            width: 42px; height: 42px; border-radius: 50%; background: rgba(3, 7, 18, 0.8);
            border: 1px solid var(--cx-gold-main); color: var(--cx-text-muted);
            display: flex; align-items: center; justify-content: center;
            cursor: pointer; transition: all 0.3s ease; box-shadow: 0 0 10px rgba(0,0,0,0.5); font-size: 1.1rem;
            position: relative; z-index: 2;
        }
        .cx-music-btn:hover { color: var(--cx-gold-light); border-color: var(--cx-gold-light); transform: scale(1.1); }
        .cx-music-btn.playing { color: var(--cx-gold-light); box-shadow: 0 0 15px rgba(217, 119, 6, 0.6); animation: spin-slow 4s linear infinite; }

        .cx-music-menu {
            position: absolute; top: 52px; right: 0;
            background: rgba(3, 7, 18, 0.95); border: 1px solid var(--cx-gold-main);
            border-radius: 4px; padding: 10px; display: flex; flex-direction: column; gap: 8px;
            opacity: 0; visibility: hidden; pointer-events: none;
            transition: all 0.2s ease; transform: translateY(-10px);
            min-width: 180px; backdrop-filter: blur(4px); box-shadow: 0 10px 20px rgba(0,0,0,0.8);
            z-index: 1;
        }
        .cx-music-menu.show { opacity: 1; visibility: visible; pointer-events: auto; transform: translateY(0); }

        .cx-progress-container { display: flex; align-items: center; gap: 5px; margin-bottom: 5px; }
        .cx-progress-time { font-size: 0.75rem; color: var(--cx-gold-light); width: 35px; text-align: center; }
        input[type="range"].cx-range { -webkit-appearance: none; width: 100%; height: 4px; background: rgba(255,255,255,0.2); border-radius: 2px; outline: none; }
        input[type="range"].cx-range::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: var(--cx-gold-main); cursor: pointer; border: 2px solid #000; }

        .cx-music-item { color: var(--cx-text-body); font-size: 0.85rem; padding: 8px 12px; cursor: pointer; border-radius: 2px; transition: all 0.2s; white-space: nowrap; border-left: 2px solid transparent; }
        .cx-music-item:hover { background: rgba(217, 119, 6, 0.2); color: var(--cx-gold-light); }
        .cx-music-item.active { color: var(--cx-gold-light); background: rgba(217, 119, 6, 0.15); border-left: 2px solid var(--cx-gold-main); }
        @keyframes spin-slow { 100% { transform: rotate(360deg); } }

        /* ================= 子页面通用 ================= */
        .sub-page-bg { position: absolute; inset: 0; background: #030712; background-image: radial-gradient(circle at 50% 50%, #1e1b4b 0%, #030712 100%); z-index: 1; }
        .sub-page-content { position: relative; z-index: 5; width: 100%; height: 100%; padding: 60px 40px 40px 40px; display: flex; flex-direction: column; }

        /* ================= 统一关闭按钮 ================= */
        .cx-btn-close-modal {
            position: absolute; top: 15px; left: 15px; right: auto; background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; color: var(--cx-text-muted);
            font-size: 1.5rem; width: 40px; height: 40px; cursor: pointer; transition: all 0.3s;
            display: flex; align-items: center; justify-content: center; z-index: 1000;
        }
        .cx-btn-close-modal:hover { color: var(--cx-danger); border-color: var(--cx-danger); background: rgba(239, 68, 68, 0.1); transform: rotate(90deg); }

        /* ================= 1. 主页 ================= */
        #home-view { display: block; background: linear-gradient(90deg, rgba(3,7,18,0.9) 0%, rgba(3,7,18,0.4) 40%, transparent 100%); }
        .home-content { position: absolute; left: 8%; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 30px; width: 80%; max-width: 400px; }
        .home-title { font-family: 'Zhi Mang Xing', cursive; font-size: clamp(3rem, 7vw, 6rem); color: var(--cx-gold-light); text-shadow: 0 5px 15px rgba(0,0,0,0.8); margin: 0; line-height: 1; }
        .home-subtitle { font-size: clamp(0.9rem, 1.8vw, 1.2rem); color: var(--cx-text-body); letter-spacing: 4px; margin-bottom: 20px; }
        .home-menu-btn { padding: 15px 30px; background: rgba(30, 27, 75, 0.4); backdrop-filter: blur(5px); border: 1px solid rgba(217, 119, 6, 0.3); border-left: 4px solid var(--cx-gold-main); color: var(--cx-text-title); font-family: 'Noto Serif SC', serif; font-size: clamp(1rem, 2vw, 1.4rem); font-weight: 700; letter-spacing: 5px; text-align: left; cursor: pointer; transition: all 0.3s ease; display: flex; align-items: center; gap: 15px; border-radius: 0 8px 8px 0; }
        .home-menu-btn:hover { background: rgba(217, 119, 6, 0.2); padding-left: 40px; border-left-color: var(--cx-gold-light); color: var(--cx-gold-light); box-shadow: 10px 0 20px rgba(0,0,0,0.5); }

        /* ================= 2. 卷首语 ================= */
        .intro-layout { display: flex; height: 100%; align-items: center; justify-content: center; padding: 20px; }
        .intro-text-box { background: linear-gradient(135deg, rgba(30, 27, 75, 0.8), rgba(3, 7, 18, 0.95)); border: 1px solid rgba(217, 119, 6, 0.3); border-radius: 8px; padding: 40px 50px; width: 90%; max-width: 800px; max-height: 85%; overflow-y: auto; box-shadow: 0 20px 50px rgba(0,0,0,0.8); text-align: center; }
        .cx-intro-content { text-align: left; color: var(--cx-text-body); line-height: 1.9; font-size: 1.1rem; margin-top: 20px; }
        .cx-intro-content b { color: var(--cx-text-title); }

        /* ================= 3. 地志 ================= */
        .map-grid { flex: 1; display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 20px; overflow-y: auto; padding: 10px 20px 30px 10px; align-content: start; }
        .cx-loc-card { background: linear-gradient(145deg, rgba(30, 27, 75, 0.6), rgba(3, 7, 18, 0.9)); border: 1px solid rgba(255,255,255,0.05); border-radius: 4px; padding: 15px 20px; cursor: pointer; transition: transform 0.3s ease, border-color 0.3s ease; display: flex; align-items: center; gap: 15px; }
        .cx-loc-card:hover { border-color: var(--cx-gold-main); transform: translateY(-3px); box-shadow: 0 8px 20px rgba(0,0,0,0.8); }
        .cx-loc-icon { width: 45px; height: 45px; background: rgba(3, 7, 18, 0.8); border: 1px solid var(--cx-glass-border); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; color: var(--cx-gold-main); transition: all 0.3s; flex-shrink: 0; }
        .cx-loc-card:hover .cx-loc-icon { background: var(--cx-gold-dark); color: var(--cx-gold-light); border-color: var(--cx-gold-light); transform: rotate(15deg); }
        .cx-loc-info { display: flex; flex-direction: column; gap: 5px; }
        .cx-loc-info h3 { margin: 0; font-size: 1.2rem; color: var(--cx-text-title); font-weight: 900; }
        .cx-loc-info span { font-size: 0.75rem; color: var(--cx-gold-light); background: rgba(217, 119, 6, 0.2); padding: 2px 6px; border-radius: 2px; width: fit-content; }

        /* 地志详情浮窗 */
        .cx-detail-page { position: absolute; inset: 0; background: rgba(3, 7, 18, 0.95); backdrop-filter: blur(8px); z-index: 500; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.3s ease; padding: 20px; cursor: pointer; }
        .cx-detail-page.show { opacity: 1; pointer-events: auto; }
        .cx-detail-box { cursor: default; width: 90%; max-width: 850px; max-height: 90%; background: linear-gradient(135deg, rgba(30, 27, 75, 0.98), #030712); border: 1px solid var(--cx-gold-main); box-shadow: 0 20px 50px rgba(0,0,0,0.9); border-radius: 8px; display: flex; flex-direction: column; transform: translateY(20px) scale(0.98); transition: transform 0.4s; position: relative; }
        .cx-detail-page.show .cx-detail-box { transform: translateY(0) scale(1); }
        .cx-detail-header { padding: 30px 40px; border-bottom: 1px solid var(--cx-glass-border); display: flex; justify-content: space-between; align-items: flex-start; background: rgba(0,0,0,0.4); }
        .cx-detail-title-area { display: flex; align-items: center; gap: 20px; }
