        .cx-btn-close-detail { flex-shrink: 0; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; color: var(--cx-text-muted); font-size: 1.8rem; width: 44px; height: 44px; cursor: pointer; transition: all 0.3s; display: flex; align-items: center; justify-content: center; margin-top: 0; z-index: 1000; position: absolute; top: 15px; left: 15px; }
        .cx-btn-close-detail:hover { color: var(--cx-danger); border-color: var(--cx-danger); background: rgba(239, 68, 68, 0.1); transform: rotate(90deg); }
        .cx-btn-close-view { position: absolute; top: 15px; left: 15px; z-index: 1000; width: 40px; height: 40px; border-radius: 4px; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); color: var(--cx-text-muted); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.3s; font-size: 1.35rem; }
        .cx-btn-close-view:hover { color: var(--cx-danger); border-color: var(--cx-danger); background: rgba(239,68,68,0.1); transform: rotate(90deg); }
