        .cx-card.is-front .cx-card-front::after { opacity: 0; }
        .cx-card-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
        .cx-card.is-front:hover .cx-card-img { transform: scale(1.05); }
        .cx-card-overlay { position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(0deg, rgba(3,7,18,0.95) 0%, rgba(3,7,18,0.8) 50%, transparent 100%); padding: 50px 15px 20px 15px; text-align: center; z-index: 10; pointer-events: none; }
        .cx-card-name { font-family: 'Zhi Mang Xing', cursive; font-size: clamp(1.8rem, 4vw, 3.5rem); color: var(--cx-gold-light); margin: 0 0 5px 0; line-height: 1; text-shadow: 0 2px 5px #000; }
        .cx-card-title { font-size: clamp(0.8rem, 1.5vw, 1.1rem); color: var(--cx-text-body); font-weight: 700; opacity: 0.9; letter-spacing: 2px; }
        .cx-click-hint { position: absolute; top: 15px; right: 15px; background: rgba(3,7,18,0.8); width: 40px; height: 40px; border-radius: 4px; display: flex; align-items: center; justify-content: center; color: var(--cx-gold-light); font-size: 1.2rem; border: 1px solid var(--cx-gold-dark); opacity: 0; transition: opacity 0.3s; z-index: 10; pointer-events: none; }
        .cx-card.is-front .cx-click-hint { opacity: 1; animation: pulse 2s infinite; }
        @keyframes pulse { 0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(217, 119, 6, 0.7); } 70% { transform: scale(1.05); box-shadow: 0 0 0 10px rgba(217, 119, 6, 0); } 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(217, 119, 6, 0); } }

        .cx-nav-btn { position: absolute; top: 50%; transform: translateY(-50%); width: 50px; height: 50px; border-radius: 4px; background: rgba(3,7,18,0.8); border: 1px solid var(--cx-text-muted); color: var(--cx-text-body); font-size: 1.5rem; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 100; transition: all 0.3s; }
        .cx-nav-btn:hover { border-color: var(--cx-gold-light); color: var(--cx-gold-light); background: rgba(217, 119, 6, 0.2); }
        .cx-nav-left { left: 5%; } .cx-nav-right { right: 5%; }

        .cx-btn-random, .cx-btn-free-start { position: absolute; bottom: 20px; padding: 12px 30px; background: linear-gradient(135deg, rgba(3, 7, 18, 0.9), rgba(15, 23, 42, 0.95)); border: 1px solid var(--cx-gold-dark); color: var(--cx-gold-light); font-family: 'Noto Serif SC', serif; font-size: clamp(0.9rem, 2vw, 1.1rem); font-weight: 900; letter-spacing: 3px; border-radius: 4px; cursor: pointer; z-index: 100; transition: all 0.3s ease; box-shadow: 0 5px 15px rgba(0,0,0,0.8); display: flex; align-items: center; gap: 10px; }
        .cx-btn-random { left: 25%; transform: translateX(-50%); }
        .cx-btn-free-start { right: 25%; transform: translateX(50%); }
        .cx-btn-random:hover, .cx-btn-free-start:hover { background: rgba(217, 119, 6, 0.2); color: #fff; border-color: var(--cx-gold-light); transform: translateX(-50%) translateY(-2px); }
        .cx-btn-free-start:hover { transform: translateX(50%) translateY(-2px); }

        /* ================= 角色详情大模态框 ================= */
        .cx-char-modal { position: absolute; inset: 0; background: rgba(3, 7, 18, 0.95); backdrop-filter: blur(10px); z-index: 600; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.4s ease; padding: 40px; cursor: pointer; }
        .cx-char-modal.show { opacity: 1; pointer-events: auto; }
        .cx-char-box {
            cursor: default; width: 100%; max-width: 1000px; height: 85%;
            background: linear-gradient(135deg, #1e1b4b, #030712); border: 1px solid var(--cx-gold-main);
            border-radius: 8px; box-shadow: 0 30px 60px rgba(0,0,0,0.9), inset 0 0 0 1px rgba(217, 119, 6, 0.2);
            display: flex; overflow: hidden; transform: scale(0.95); transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            position: relative;
