        .cx-char-right { width: 55%; padding: 50px 40px; display: flex; flex-direction: column; position: relative; z-index: 2; }
        .cx-char-header { display: flex; align-items: center; gap: 25px; margin-bottom: 30px; border-bottom: 1px dashed var(--cx-glass-border); padding-bottom: 25px; }
        .cx-char-avatar { width: 90px; height: 90px; border-radius: 50%; border: 2px solid var(--cx-gold-main); object-fit: cover; box-shadow: 0 5px 15px rgba(0,0,0,0.6); }
        .cx-char-info h2 { font-family: 'Zhi Mang Xing', cursive; font-size: clamp(2rem, 4vw, 3rem); color: var(--cx-text-title); margin: 0 0 5px 0; letter-spacing: 2px; }
        .cx-char-tag { font-size: 0.9rem; background: rgba(217, 119, 6, 0.2); color: var(--cx-gold-light); padding: 4px 12px; border-radius: 4px; border: 1px solid rgba(217, 119, 6, 0.3); }
