        .cx-btn-select-big { margin-top: 30px; width: 100%; padding: 18px 0; background: rgba(217, 119, 6, 0.15); border: 1px solid var(--cx-gold-main); border-radius: 4px; color: var(--cx-gold-light); font-family: 'Noto Serif SC', serif; font-weight: 900; font-size: 1.3rem; letter-spacing: 5px; cursor: pointer; transition: all 0.3s; box-shadow: 0 5px 15px rgba(0,0,0,0.5); }
        .cx-btn-select-big:hover { background: var(--cx-gold-main); color: #fff; transform: translateY(-3px); box-shadow: 0 10px 25px rgba(217, 119, 6, 0.4); }

        /* ================= 自由开局浮窗 ================= */
        .cx-modal { position: absolute; inset: 0; background: rgba(3, 7, 18, 0.95); backdrop-filter: blur(8px); z-index: 500; display: flex; align-items: center; justify-content: center; opacity: 0; pointer-events: none; transition: opacity 0.4s ease; padding: 20px; cursor: pointer; }
        .cx-modal.show { opacity: 1; pointer-events: auto; }
        .cx-modal-box { cursor: default; position: relative; width: 100%; max-width: 900px; background: linear-gradient(135deg, rgba(30, 27, 75, 0.98), #030712); border: 1px solid var(--cx-gold-main); box-shadow: 0 20px 50px rgba(0,0,0,0.9); padding: 40px; border-radius: 8px; display: flex; flex-direction: column; align-items: center; transform: translateY(20px); transition: transform 0.4s; max-height: 100%; overflow-x: hidden; overflow-y: auto; }
        .cx-modal.show .cx-modal-box { transform: translateY(0); }
        .cx-modal-title { font-family: 'Zhi Mang Xing', cursive; font-size: clamp(2rem, 4vw, 3rem); color: var(--cx-gold-light); margin: 0 0 10px 0; text-shadow: 0 2px 10px rgba(217, 119, 6, 0.4); letter-spacing: 4px; }
        .cx-modal-subtitle { color: var(--cx-text-muted); margin-bottom: 30px; letter-spacing: 2px; font-size: 0.95rem; text-align: center; }

        .cx-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; width: 100%; margin-bottom: 30px; }
        .cx-form-group { display: flex; flex-direction: column; gap: 8px; width: 100%; }
        .cx-form-group.full-width { grid-column: 1 / -1; }
        .cx-form-label { font-size: 1rem; color: var(--cx-gold-light); font-weight: bold; letter-spacing: 1px; }
        .cx-form-input, .cx-form-select, .cx-form-textarea { background: rgba(3, 7, 18, 0.8); border: 1px solid var(--cx-glass-border); border-radius: 4px; padding: 12px 15px; color: var(--cx-text-body); font-family: 'Noto Serif SC', serif; font-size: 1rem; transition: all 0.3s; outline: none; width: 100%; }
        .cx-form-input:focus, .cx-form-select:focus, .cx-form-textarea:focus { border-color: var(--cx-gold-light); background: rgba(30, 27, 75, 0.6); }
        .cx-form-textarea { min-height: 100px; resize: vertical; }
        .cx-stone-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
        .cx-stone-field { display: flex; flex-direction: column; gap: 6px; }
        .cx-stone-field span { color: var(--cx-text-muted); font-size: 0.85rem; }

        .cx-custom-item-row { background: rgba(3, 7, 18, 0.5); border: 1px solid rgba(255,255,255,0.05); padding: 15px; border-radius: 4px; margin-bottom: 12px; transition: all 0.3s; width: 100%; }
