            .cx-music-wrapper { top: 15px; right: 15px; }

            /* 轮盘导航按钮向内缩，防止超出屏幕 */
            .cx-nav-left { left: 2%; width: 40px; height: 40px; }
            .cx-nav-right { right: 2%; width: 40px; height: 40px; }

            /* 底部按钮缩小 */
            .cx-btn-random { left: 5px; transform: none; padding: 10px 15px; font-size: 0.9rem; }
            .cx-btn-free-start { right: 5px; transform: none; padding: 10px 15px; font-size: 0.9rem; }
            .cx-btn-random:hover { transform: translateY(-2px); }
            .cx-btn-free-start:hover { transform: translateY(-2px); }
        }
