            selectedFabao = fabaos.find(f => f.id === $(this).data('id'));
            try {
                const enabledXiaoSuo = await WorldbookManager.applyFabaoEntryState(selectedFabao);
                await runStEcho(enabledXiaoSuo ? '小索【人设】已开启。' : '小索【人设】已关闭。', 'success');
            } catch (err) {
                await runStEcho('小索条目切换失败：' + err.message, 'error');
            }
        });

        // ================= 数据库：苍玄界 18 位角色 =================
        const characters = [
            { id: 1, name: "沈慕微", sect: "天剑宗", title: "戏精面瘫师尊", front: "https://i.postimg.cc/7YHrrRJx/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3297147603.png", avatar: "https://i.postimg.cc/Nf4V2XhJ/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1265307928.png", desc: "表面断情绝爱天下第一，背地里面瘫撸兔，其实根本没修无情道的戏精师尊。" },
            { id: 2, name: "江念", sect: "天剑宗", title: "雀跃热忱的无情道假粉", front: "https://i.postimg.cc/3J8QQq08/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1003244661.png", avatar: "https://i.postimg.cc/7ZZR3LDK/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1259744848.png", desc: "因为觉得师尊挥剑太帅而入无情道，根本不懂无情为何物。天生精力旺盛、对谁都自来熟的热忱话唠。" },
            { id: 3, name: "冷小凝", sect: "天剑宗", title: "高冷八卦狗仔", front: "https://i.postimg.cc/qMJHHF68/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_2168962348.png", avatar: "https://i.postimg.cc/9QQkdfVx/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_295505417.png", desc: "表面冰冷无情道模范，背地里是天剑宗头号八卦狗仔，为你疯狂爆更小报。" },
            { id: 4, name: "印唯心", sect: "魔道六门", title: "乐子人魔门圣女", front: "https://i.postimg.cc/15m11dV8/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3012415577.png", avatar: "https://i.postimg.cc/Njjn60Bw/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_2867104877.png", desc: "杀不杀你全看今天掷骰子点数的乐子人圣女，觉得你有趣比阵营立场重要一百倍。" },
            { id: 5, name: "妖九烟", sect: "妖族", title: "霸道护食妖皇", front: "https://i.postimg.cc/ncFffW97/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_4197123255.png", avatar: "https://i.postimg.cc/fRRPcbZq/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1721347458.png", desc: "满脑子都是“这人类能不能吃”和“这人类挺好玩先留着”的霸道妖皇，极度护食。" },
            { id: 6, name: "药芷若", sect: "丹霞谷", title: "腹黑试药姐姐", front: "https://i.postimg.cc/8PpggYfP/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_344785272.png", avatar: "https://i.postimg.cc/8zzYRCNQ/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_2591833600.png", desc: "表面温婉叫你弟弟，背地里算盘打得震天响，随时准备拿你试药的腹黑姐姐。" },
            { id: 7, name: "慕海棠", sect: "阵道阁", title: "重度嗜睡阵法痴", front: "https://i.postimg.cc/5N4WWrQH/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3394233994.png", avatar: "https://i.postimg.cc/FHH6yKmn/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1704310586.png", desc: "懒到能在沙盘上睡觉的天才，顺手画个阵就能把你困三天，对不按套路的灵力极度狂热。" },
            { id: 8, name: "谢忘生", sect: "玄清宗", title: "佛系种田宗主", front: "https://i.postimg.cc/HW41KmnY/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_2648331644.png", avatar: "https://i.postimg.cc/650S4ZsV/1-2-artist-shion(mirudakemann)-0-6-artist-ciloranko-0-8-artist-kushima-yu-s-2576050650.png", desc: "满脑子只有种田的佛系宗主，哪怕敌袭也要先把灵土转移，打架不如翻地。" },
            { id: 9, name: "萧天衍", sect: "太虚观", title: "死要钱半仙神棍", front: "https://i.postimg.cc/wxcYPzMT/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1630298590.png", avatar: "https://i.postimg.cc/Bnff9FWK/1-2-artist-shion(mirudakemann)-0-6-artist-ciloranko-0-8-artist-kushima-yu-s-736807161.png", desc: "泄露天机被罚滞留人间的神棍，推演说话永远只说一半，死要钱且绝不包售后。" },
            { id: 10, name: "颂长风", sect: "御兽宗", title: "野兽派狼群首领", front: "https://i.postimg.cc/c1MGjWCs/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3923437469.png", avatar: "https://i.postimg.cc/vHzjxnR5/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1247479660.png", desc: "靠闻气味识人的护短野兽派，身上没血腥味才能好好说话，比起人类更信任狼群。" },
            { id: 11, name: "姜昭昭", sect: "承安皇朝", title: "修仙狂热假小子", front: "https://i.postimg.cc/3wJYMJH2/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3711123299.png", avatar: "https://i.postimg.cc/43NsCNTh/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1559030753.png", desc: "天天粘着你问修仙百科的假小子公主，翻墙比侍卫还快，花重金买了一抽屉骗人秘籍。" },
            { id: 12, name: "苏酒儿", sect: "承安皇朝", title: "笑面情报老板娘", front: "https://i.postimg.cc/wBTgKTdX/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_3929283289.png", avatar: "https://i.postimg.cc/7LYwvYy7/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1743935713.png", desc: "用一碟猪耳朵就能套出你宗门机密的客栈老板娘，笑眯眯的情报贩子，算盘打得比谁都精。" },
            { id: 13, name: "姜澄鸢", sect: "承安皇朝", title: "硬核护犊子人皇", front: "https://i.postimg.cc/pdXRNXtJ/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_4278133882.png", avatar: "https://i.postimg.cc/g0km9kPh/1_2_artist_shion(mirudakemann)_0_6_artist_ciloranko_0_8_artist_kushima_yu_s_1742317145.png", desc: "天道罩着的硬核女皇，一边给离家出走的闺女收拾烂摊子，一边跟你平起平坐谈仙凡规矩。" },
            { id: 14, name: "红", sect: "天剑宗", title: "上古剑灵老古董", front: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/道友录红.png", avatar: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/红头像.png", desc: "沉睡万年的上古残损剑灵，极度护食且讨厌飞升，一边嘲讽现代剑修一边骗吃骗喝。" },
            { id: 15, name: "雪照宁", sect: "冰原雪域", title: "风雪堂小医仙", front: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/道友录雪照宁.png", avatar: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/雪照宁头像.png", desc: "雪域风雪堂医师，进门只看伤不问仇，温柔递药时也能把医馆规矩守得很硬。" },
            { id: 16, name: "潮听澜", sect: "沧溟海阙", title: "重诺干练海公主", front: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/道友录潮听澜.png", avatar: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/潮听澜头像.png", desc: "沧溟海阙海公主兼海图司少司潮，长发高束、提刀巡海，重诺到能把风浪也算进承诺里。" },
            { id: 17, name: "凌长霜", sect: "玄霜宫", title: "把关心写进附录的宫主", front: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/道友录凌长霜.png", avatar: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/凌长霜头像.png", desc: "玄霜宫宫主，外表冰雪条例，内里八卦情报库，照顾人时会先翻规章再递热汤。" },
            { id: 18, name: "银摇枝", sect: "百蛊绿洲", title: "蛊铃一响账也要清的寨主", front: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/道友录银摇枝.png", avatar: "https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/银摇枝头像.png", desc: "百蛊绿洲寨主，苗疆异域风情下的实干派管理者，给蛊虫起名像给饭菜点单。" }
        ];

        // ================= 数据库：苍玄大地图 =================
        const locations = [
            { id: "xuanqing", name: "玄清宗", tag: "中州腹地 · 正道核心", icon: "fa-yin-yang", desc: "<p>位于中州太行灵脉之上的天下正道魁首，亦是苍玄界明面上的秩序维护者。</p><p>宗门内规矩森严，等级分明，以传统的炼气修仙为主。其护宗大阵“太清四象阵”号称能抵挡大乘期修士的全力一击。</p><p><strong>风物：</strong>随处可见的青玉广场与仙鹤，弟子皆穿素白道袍，行事板正。这里的灵气最为纯粹平和，极适合打坐修炼。</p>" },
            { id: "tianjian", name: "天剑宗", tag: "西境边界 · 断剑山脉", icon: "fa-khanda", desc: "<p>坐落于西境环境恶劣的断剑山脉，是全天下剑修的最高殿堂。</p><p>不讲究繁文缛节，只信奉“一剑破万法”。宗门内的建筑多是在悬崖峭壁上硬生生开凿出来的，主峰名为“天极峰”，峰顶常年积雪，剑气缭绕。</p><p><strong>风物：</strong>空气中总是弥漫着金属的冷厉与剑意的肃杀，宗门内最常听到的声音就是利刃出鞘与金铁交鸣。</p>" },
            { id: "taixu", name: "太虚观", tag: "九天之上 · 浮云秘境", icon: "fa-cloud-sun", desc: "<p>苍玄界最神秘的宗门，主体建筑漂浮在中州上空的云层之中，普通人终其一生也难窥其真貌。</p><p>门下弟子极少在世间走动，他们擅长推演天机、星象卜卦，自诩为“天道观察者”。</p><p><strong>风物：</strong>建筑多为虚幻的星光与云气凝结，没有重力概念，弟子常手持罗盘或龟甲，说话总是说一半留一半。</p>" },
            { id: "danxia", name: "丹霞谷", tag: "南域 · 神农鼎遗迹", icon: "fa-mortar-pestle", desc: "<p>位于南域的巨大裂谷之中，气候温暖湿润，是天下九成极品丹药的产出地。</p><p>谷内奇花异草遍地，但越美丽的地方越危险，外围的天然毒瘴让无数贪婪的散修有来无回。</p><p><strong>风物：</strong>终年被五彩斑斓的药气笼罩，随处可见巨大的炼丹炉虚影。这里的修士往往随身带着无数个装满未知药粉的瓶瓶罐罐。</p>" },
            { id: "wanqi", name: "万器山", tag: "西域 · 十万火山", icon: "fa-hammer", desc: "<p>坐落于西域的活火山群之中，利用地心熔岩之火进行法宝锻造。</p><p>这里的修士大多身材魁梧，无论男女都崇尚力量与极致的肉身防御。全大陆最顶级的法宝和防具皆出自于此。</p><p><strong>风物：</strong>炽热、烟尘、永不停歇的打铁声。山门前堆满了失败的法宝残骸，被他们戏称为“艺术的阶梯”。</p>" },
            { id: "desert", name: "赤铃沙海", tag: "西南边陲 · 百蛊绿洲", icon: "fa-bell", desc: "<p>位于苍玄界西南边陲、万器山以南与十万大山以西的广阔边缘沙海，沙风里常夹着银铃与蛊虫振翅声。</p><p>百蛊绿洲是沙海核心寨城，外来修士入寨需登记蛊契；鸣沙驿负责沙舟航线，赤沙禁域则是连老向导都要先摸护身符的高危区。</p><p><strong>风物：</strong>苗疆式银饰、彩布、蛊棚、水井账册和沙舟驼铃混在一起，热闹时像集市，严肃时像账房点名。</p>" },
            { id: "zhendao", name: "阵道阁", tag: "沧溟外海 · 阵道群岛", icon: "fa-draw-polygon", desc: "<p>孤悬于沧溟外海之上的群岛，由无数个上古连环阵法构成，整体像一座巨大的水上迷宫。</p><p>没有阵道阁的指引，外人连岛的边缘都摸不到。他们将阵法融入了生活的方方面面，甚至连吃饭的桌子都刻着保鲜阵。</p><p><strong>风物：</strong>海浪与星光交织，脚下的石板可能随时翻转把你传送到海里。这里的修士大多带着严重的黑眼圈，手里永远拿着阵图沙盘。</p>" },
            { id: "cangming", name: "沧溟海阙", tag: "沧溟内缘 · 潮汐海阙", icon: "fa-water", desc: "<p>位于星罗群岛以东、无尽海内缘以西的新兴海修势力，外界常以沧溟外海统称，真正熟悉航路的人会称其为沧溟海阙。</p><p>海阙由海修、鲛人、潮汐术士与巡潮使共同维持，掌管潮汐航路、海图许可与归墟外围封锁。外来者入阙必须领取潮印，否则会被潮汐阵送回龙绡渡。</p><p><strong>风物：</strong>半在海面半在水下的玄玉宫阙、夜间倒映星潮的潮听台、用鲛珠照明的海图司，以及随时可能改道的潮汐阵路。</p>" },
            { id: "xueyu", name: "冰原雪域", tag: "北境极寒 · 玄霜宫辖境", icon: "fa-snowflake", desc: "<p>位于苍玄界最北端，南接中州商道，北临永昼冰海，是玄霜宫镇守寒灾与白夜裂谷的边境雪域。</p><p>外来修士通常从寒渊冰市入境，购买抗寒符、租雪舟、办理雪路通行。暴雪季普通飞舟航线会失效，路引比豪言壮语可靠得多。</p><p><strong>风物：</strong>白昼漫长，风雪削灵，冰街上热汤棚与寒铁行并排营业。玄霜宫巡霜使常年巡逻，专治把勇气当棉袄的低阶修士。</p>" },
            { id: "yushou", name: "御兽宗", tag: "南疆 · 万兽山脉", icon: "fa-paw", desc: "<p>建立在南疆原始森林的边缘，门下弟子皆与妖兽签订契约，共同战斗。</p><p>相比于人类的狡诈，他们更信任灵兽的直觉。宗门内没有宏伟的大殿，多是依树而建的木屋或巨大的兽穴。</p><p><strong>风物：</strong>震天的兽吼、浓郁的野兽气息。弟子们身上多带有野兽的特征（如狼耳、蛇瞳），行事狂野不羁。</p>" },
            { id: "yaozu", name: "妖族王庭", tag: "南境深处 · 十万大山", icon: "fa-dragon", desc: "<p>被人类修士列为禁地的十万大山深处，是妖族繁衍生息的绝对领地。</p><p>这里不修金丹元婴，只修血脉与内丹。由几大上位妖族共同统治，极度排外，人类踏入通常只有成为食物或奴隶两个下场。</p><p><strong>风物：</strong>巨大到遮天蔽日的远古巨树，充满原始压迫感的图腾，以及空气中随时会让人陷入疯狂的妖气。</p>" },
            { id: "modao", name: "魔道六门", tag: "苍玄地下 · 暗河网络", icon: "fa-skull", desc: "<p>由六个松散联盟组成的魔修势力总称，藏匿于贯穿苍玄界地下的庞大暗河与溶洞网络中。</p><p>这里没有道德的束缚，只有赤裸裸的利益与力量。虽然被正道追杀，但却是黑市交易和情报流通最繁荣的地方。</p><p><strong>风物：</strong>暗红色的地下荧光苔藓、随处可见的黑市摊位、戴着面具掩藏身份的亡命之徒，以及充满诱惑与危险的修罗殿。</p>" },
            { id: "guiyu", name: "幽冥渊", tag: "西境极渊 · 鬼域底部", icon: "fa-ghost", desc: "<p>位于大陆最西端的一道深不见底的深渊，是传说中连接冥界的入口。</p><p>这里没有活人的生气，只有刺骨的阴风和游荡的残魂。少数修炼鬼道的邪修会冒险进入边缘收集阴气，但深入者从未有人生还。</p><p><strong>风物：</strong>绝对的黑暗与冰冷，耳边永远萦绕着若有若无的低泣。忘川河水在此汇聚，洗刷着一切前尘记忆。</p>" },
            { id: "tianyuan", name: "天渊城", tag: "中立交界 · 散修联盟总部", icon: "fa-city", desc: "<p>建立在正魔交界处的一座奇迹之城，受三大顶级宗门共同监督，是绝对的中立区。</p><p>城内严禁私斗，违者会遭到大阵的无情抹杀。这里是散修的天堂，只要你有灵石，可以买到任何功法、丹药甚至是某位大能的项上人头。</p><p><strong>风物：</strong>终日不歇的喧嚣，鳞次栉比的商铺与拍卖行。你可能在街边吃面的同时，看到两个化神期老怪在为一个地摊货讨价还价。</p>" },
            { id: "chengan", name: "承安皇朝", tag: "中州平原 · 太行以南", icon: "fa-vihara", desc: "<p>坐落于苍玄界最肥沃的中州平原盆地，是凡人世界最庞大、最强盛的皇朝。</p><p>与修仙宗门划江而治，井水不犯河水。这里不修仙法，但武道昌盛，皇朝的精锐铁骑配合军阵，甚至能抗衡元婴期修士。当代人皇姜澄鸢更是受天道气运加身，威压极重。</p><p><strong>风物：</strong>金碧辉煌的宫殿群、市井繁华的烟火气、严密的城防与听风楼里络绎不绝的情报客。这里没有长生不老的幻想，只有实打实的权谋与国泰民安。</p>" }
        ];

        // ================= 渲染地图与选项 =================
        const ALL_REALMS = ["炼气一层", "筑基一层", "金丹一层", "元婴一层", "化神一层", "炼虚一层", "合体一层", "大乘一层", "渡劫一层", "半步真仙", "真仙大成"];
        const $realmSelect = $('#fs-realm');
        $realmSelect.append(`<option value="自定义">-- 自定义 --</option>`);
        ALL_REALMS.forEach(r => $realmSelect.append(`<option value="${r}">${r}</option>`));
        $realmSelect.val("炼气一层");

        $realmSelect.on('change', function() {
            if ($(this).val() === '自定义') $('#fs-realm-custom').show().focus();
            else $('#fs-realm-custom').hide();
        });

        const $locSelect = $('#fs-location');
        $locSelect.append(`<option value="自定义">-- 自定义 --</option>`);

        const $mapTrack = $('#cx-map-track');
        locations.forEach((loc) => {
            $locSelect.append(`<option value="${loc.name}">${loc.name} (${loc.tag})</option>`);
            $mapTrack.append(`
                <div class="cx-loc-card" data-id="${loc.id}">
                    <div class="cx-loc-icon"><i class="fa-solid ${loc.icon}"></i></div>
                    <div class="cx-loc-info"><h3>${loc.name}</h3><span>${loc.tag}</span></div>
                </div>
            `);
        });
        $locSelect.val("玄清宗");
        $locSelect.on('change', function() {
            if ($(this).val() === '自定义') $('#fs-location-custom').show().focus();
            else $('#fs-location-custom').hide();
        });

        const pageDetail = document.getElementById('cx-detail-page');
        $('.cx-loc-card').on('click', function() {
            const id = $(this).data('id');
            const data = locations.find(l => l.id === id);
            $('#dt-icon').html(`<i class="fa-solid ${data.icon}"></i>`);
            $('#dt-name').text(data.name);
            $('#dt-tag').text(data.tag);
            $('#dt-desc').html(data.desc);
            pageDetail.classList.add('show');
        });

        // ================= 渲染与控制 3D 轮盘 =================
        const $track = $('#cx-track');
        const total = characters.length;
        const angleStep = 360 / total;
        let currentAngle = 0;
        let frontIndex = 0;
        let isAnimating = false;

        characters.forEach((char, index) => {
            const floatDelay = -(Math.random() * 4).toFixed(2);
            $track.append(`
                <div class="cx-card" data-index="${index}" data-id="${char.id}">
                    <div class="cx-card-float" style="animation-delay: ${floatDelay}s;">
                        <div class="cx-card-inner">
                            <div class="cx-card-front">
                                <img src="${char.front}" class="cx-card-img" loading="lazy">
                                <div class="cx-click-hint"><i class="fa-solid fa-eye"></i></div>
                                <div class="cx-card-overlay">
                                    <h3 class="cx-card-name">${char.name}</h3>
                                    <div class="cx-card-title">${char.title}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            `);
        });

        const $cards = $('.cx-card');

        window.updateCarousel = function() {
            const containerHeight = document.querySelector('.cx-3d-scene').clientHeight;
            const cardHeight = containerHeight * 0.65;
            const cardWidth = cardHeight * (2 / 3);

            // 移动端智能缩小轮盘半径，防止卡片超出屏幕
            const radiusOffset = window.innerWidth < 768 ? 70 : 150;
            const radius = Math.round((cardWidth / 2) / Math.tan(Math.PI / total)) + radiusOffset;

            $cards.each(function(index) {
                let angle = currentAngle + (index * angleStep);
                let rad = angle * (Math.PI / 180);
                let x = Math.sin(rad) * radius;
                let z = Math.cos(rad) * radius - radius;
                let normalizedAngle = angle % 360;
                if (normalizedAngle < 0) normalizedAngle += 360;
                let isFront = (normalizedAngle < 5 || normalizedAngle > 355);
                let scale = 0.6 + ((z + radius) / (radius * 2)) * 0.4;

                if (isFront) { scale = 1.1; frontIndex = index; }

                $(this).css({
                    'transform': `translate(-50%, -50%) translateX(${x}px) translateZ(${z}px) scale(${scale})`,
                    'z-index': Math.round(z + radius)
                });
                if (isFront) $(this).addClass('is-front');
                else $(this).removeClass('is-front');
            });
        };

        // ================= 角色弹窗逻辑 =================
        const charModal = document.getElementById('cx-char-modal');
        const cmFront = document.getElementById('cm-front');
        const cmAvatar = document.getElementById('cm-avatar');
        const cmName = document.getElementById('cm-name');
        const cmSect = document.getElementById('cm-sect');
        const cmTitle = document.getElementById('cm-title');
        const cmDesc = document.getElementById('cm-desc');
        const cmBtnSelect = document.getElementById('cm-btn-select');

        $cards.on('click', function(e) {
            if (isAnimating) return;
            const clickedIndex = $(this).data('index');

            if (clickedIndex === frontIndex) {
                const charData = characters[clickedIndex];
                cmFront.src = charData.front;
                cmAvatar.src = charData.avatar;
