        function getCxGlobal(name) {
            try {
                if (globalThis[name] !== undefined) return globalThis[name];
            } catch (_) {}
            try {
                if (window.parent && window.parent !== window && window.parent[name] !== undefined) return window.parent[name];
            } catch (_) {}
            return undefined;
        }

        function setCxRegexEnabled(regex, enabled) {
            if (!regex) return;
            const hasDisabled = Object.prototype.hasOwnProperty.call(regex, 'disabled');
            const hasEnabled = Object.prototype.hasOwnProperty.call(regex, 'enabled');
            if (hasDisabled) regex.disabled = !enabled;
            if (hasEnabled) regex.enabled = enabled;
            if (!hasDisabled && !hasEnabled) regex.disabled = !enabled;
        }

        async function activateFreeStartRegexAndRerender() {
            const updateRegexes = getCxGlobal('updateTavernRegexesWith');
            if (typeof updateRegexes === 'function') {
                try {
                    await updateRegexes(regexes => {
                        for (const regex of regexes) {
                            const name = regex && (regex.scriptName || regex.script_name || regex.name || '');
                            if (name === '自由开局美化') setCxRegexEnabled(regex, true);
                        }
                        return regexes;
                    }, { type: 'character', name: 'current' });
                } catch (error) {
                    console.warn('cx free-start regex activation failed', error);
                }
            }

            const emit = getCxGlobal('eventEmit');
            const events = getCxGlobal('tavern_events');
            if (typeof emit === 'function' && events && events.MESSAGE_UPDATED) {
                try {
                    await emit(events.MESSAGE_UPDATED, 0);
                } catch (error) {
                    console.warn('cx free-start message update event failed', error);
                }
            }

            if (typeof setChatMessages === 'function') {
                try {
                    await setChatMessages([{ message_id: 0 }], { refresh: 'affected' });
                    return;
                } catch (error) {
                    console.warn('cx free-start rerender failed', error);
                }
            }

            const rerender = getCxGlobal('reloadAndRenderChatWithoutEvents');
            if (typeof rerender === 'function') {
