  };

  function migrateCgStateObject(map) {
    if (!map || typeof map !== "object" || Array.isArray(map)) return false;
    let touched = false;
    for (const [oldId, newId] of Object.entries(CG_RENAME_MAP)) {
      if (Object.prototype.hasOwnProperty.call(map, oldId)) {
        if (map[oldId] === true && map[newId] !== true) map[newId] = true;
        delete map[oldId];
        touched = true;
      }
    }
    return touched;
  }

  function migrateStoredCGVariables() {
    if (typeof updateVariablesWith !== "function") {
      setTimeout(migrateStoredCGVariables, 2000);
      return;
    }
    try {
      updateVariablesWith((variables) => {
        const next = variables && typeof variables === "object" ? variables : {};
        migrateCgStateObject(next._CG相册);
        return next;
      }, { type: "character" });
    } catch (e) {
      console.warn("[CG Manager] CG 变量迁移失败:", e);
    }
  }

  function ensureCharacterCGVariables() {
