    return null;
  }

  function requireHelper(methods) {
    const api = {};
    for (const method of methods) {
      const fn = getHelperFunction(method);
      if (!fn) throw new Error(`酒馆助手缺少 ${method} 接口`);
      api[method] = fn;
    }
    return api;
  }

  function asCleanText(value, maxLength = 160) {
    return String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, maxLength);
  }

  function asCleanMultiline(value, maxLength = 6000) {
    return String(value ?? '')
      .replace(/\r\n?/g, '\n')
      .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
      .trim()
      .slice(0, maxLength);
  }

  function asWorldbookBody(value) {
    return String(value ?? '')
      .replace(/\r\n?/g, '\n')
      .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
      .trim()
      .slice(0, 900000);
  }

  function normalizeRemoteImageUrl(value) {
    const url = asCleanText(value, 2048);
    if (!url) return '';
    try {
      const parsed = new URL(url);
      if ((parsed.protocol === 'http:' || parsed.protocol === 'https:') && parsed.hostname) return url;
    } catch (_) {}
    return '';
  }

  function normalizePlayerAvatarValue(value) {
    const url = asCleanText(value, 900000);
    if (!url) return '';
    if (/^(https?:\/\/|data:image\/)/i.test(url)) return url;
    return '';
  }

  function cssStringValue(value) {
    return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, ' ');
  }

  function cssUrlValue(value) {
    return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '%22').replace(/[\r\n]/g, '');
  }

  function escapeRegExp(value) {
    const specials = '\\^$.*+?()[]{}|/-';
    return Array.from(String(value || '')).map(char => specials.includes(char) ? '\\' + char : char).join('');
  }

  function roleAvatarUrl(role) {
    if (!role || typeof role !== 'object') return '';
    return normalizeRemoteImageUrl(role.defaultImg || role.avatar || role.avatarUrl || role.avatar_url || role.default_img || role.imageUrl || role.image_url || role.image || role.icon || role.portraitImg || role.portrait || role.portraitUrl || role.portrait_url);
  }

  function buildDialogueCustomRoleAvatarBlock(roles = loadCustomRoles()) {
    const css = (Array.isArray(roles) ? roles : [])
      .map(role => {
        const name = asCleanText(role.name || role.label, 80);
        const avatar = roleAvatarUrl(role);
        if (!name || !avatar) return '';
        const selectorName = cssStringValue(name);
        const url = cssUrlValue(avatar);
        return `.cxd-row[data-name="${selectorName}"] .cxd-avatar::after { content: "" !important; }\n.cxd-row[data-name="${selectorName}"] .cxd-avatar { background-image: url("${url}") !important; }`;
      })
      .filter(Boolean)
      .join('\n');
    if (!css) return '';
    return `${DIALOG_AVATAR_BLOCK_START}\n${css}\n${DIALOG_AVATAR_BLOCK_END}\n`;
  }

  function replaceDialogueAvatarBlock(replaceString, block) {
    const source = String(replaceString || '');
    const markerPattern = new RegExp(`${escapeRegExp(DIALOG_AVATAR_BLOCK_START)}[\\s\\S]*?${escapeRegExp(DIALOG_AVATAR_BLOCK_END)}\\n?`, 'g');
    const withoutOldBlock = source.replace(markerPattern, '');
    if (!block) return withoutOldBlock;
    if (withoutOldBlock.includes('</style>')) return withoutOldBlock.replace('</style>', `${block}</style>`);
    return `${withoutOldBlock}\n<style>\n${block}</style>`;
  }

  function tavernRegexName(regex) {
    return String(regex?.script_name ?? regex?.scriptName ?? '');
  }

  function tavernRegexReplaceString(regex) {
    return String(regex?.replace_string ?? regex?.replaceString ?? '');
  }

  function setTavernRegexReplaceString(regex, replaceString) {
    const next = { ...regex };
    if ('replace_string' in next || !('replaceString' in next)) next.replace_string = replaceString;
    if ('replaceString' in next) next.replaceString = replaceString;
    return next;
  }

  async function syncDialogueCustomRoleAvatarRegex(reason = 'workshop-custom-role') {
    const updateRegexes = getHelperFunction('updateTavernRegexesWith');
    if (typeof updateRegexes !== 'function') {
      console.warn('[苍玄界创意工坊] 酒馆助手缺少 updateTavernRegexesWith，无法写入对话美化头像');
      return false;
    }
    const block = buildDialogueCustomRoleAvatarBlock();
    let matched = false;
    let changed = false;
    try {
      await updateRegexes(regexes => {
        const list = Array.isArray(regexes) ? regexes : [];
        return list.map(regex => {
          if (tavernRegexName(regex) !== DIALOG_REGEX_SCRIPT_NAME) return regex;
          matched = true;
          const before = tavernRegexReplaceString(regex);
          const after = replaceDialogueAvatarBlock(before, block);
          if (after === before) return regex;
          changed = true;
          return setTavernRegexReplaceString(regex, after);
        });
      }, { type: 'character', name: 'current' });
      if (!matched) console.warn('[苍玄界创意工坊] 未找到对话美化头像绑定目标正则', reason);
      else if (!changed) console.info('[苍玄界创意工坊] 对话美化头像绑定无需更新', reason);
      return changed;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 写入对话美化头像绑定失败', error);
      return false;
    }
  }
  function queueDialogueCustomRoleAvatarRegexSync(reason = 'workshop-custom-role') {
    try {
      if (state.avatarRegexSyncTimer) hostWindow.clearTimeout(state.avatarRegexSyncTimer);
      state.avatarRegexSyncTimer = hostWindow.setTimeout(() => {
        state.avatarRegexSyncTimer = null;
        syncDialogueCustomRoleAvatarRegex(reason);
      }, 250);
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 排队写入对话美化头像失败', error);
      syncDialogueCustomRoleAvatarRegex(reason);
      return false;
    }
  }

  function normalizeCustomRole(role) {
    if (!role || typeof role !== 'object') return null;
    const name = asCleanText(role.name || role.label, 40);
    const defaultImg = normalizeRemoteImageUrl(role.defaultImg || role.default_img || role.avatar || role.avatarUrl || role.avatar_url || role.imageUrl || role.image_url || role.image || role.icon);
    const portraitImg = normalizeRemoteImageUrl(role.portraitImg || role.portrait_img || role.portrait || role.portraitUrl || role.portrait_url || role.coverUrl || role.cover_url || defaultImg);
    const sect = asCleanText(role.sect || role.group || '自定义', 40) || '自定义';
    const profile = asCleanMultiline(role.profile || role.lore || role.setting || role.description || role.prompt || role.promptText || '', 12000);
    if (!name || !defaultImg) return null;
    const moduleId = asCleanText(role.moduleId || role.module_id || '', 120);
    const entryId = asCleanText(role.entryId || role.entry_id || '', 120);
    return { name, defaultImg, portraitImg: portraitImg || defaultImg, sect, profile, custom: true, source: 'workshop', moduleId, entryId };
  }

  function workshopRoleKey(role) {
    return [role?.moduleId || '', role?.entryId || '', role?.name || ''].join('::');
  }

  function getEffectiveCustomRoles(roles = loadCustomRoles()) {
    const roleMap = new Map();
    (Array.isArray(roles) ? roles : []).forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) roleMap.set(normalized.name, normalized);
    });
    return [...roleMap.values()];
  }

  function loadStatusbarManualRoles() {
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(STATUS_ROLE_STORAGE_KEY) || '[]');
      return Array.isArray(parsed) ? parsed.map(role => normalizeCustomRole(role)).filter(Boolean) : [];
    } catch (_) {
      return [];
    }
  }

  function getMvuObj() {
    return hostWindow.Mvu || window.Mvu || (typeof Mvu !== 'undefined' ? Mvu : null);
  }

  function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function loadCustomRoles() {
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(CUSTOM_ROLE_STORAGE_KEY) || '[]');
      if (!Array.isArray(parsed)) return [];
      const roleMap = new Map();
      parsed.forEach(role => {
        const normalized = normalizeCustomRole(role);
        if (normalized) roleMap.set(workshopRoleKey(normalized), normalized);
      });
      return [...roleMap.values()];
    } catch (_) {
      return [];
    }
  }

  function notifyStatusbarExternalRoles() {
    const api = getStatusbarRoleApi();
    if (!api || typeof api.syncExternal !== 'function') return false;
    try {
      const result = api.syncExternal();
      if (result && typeof result.catch === 'function') result.catch(() => {});
      return true;
    } catch (_) {
      return false;
    }
  }

  function saveCustomRoles(roles) {
    const roleMap = new Map();
    (Array.isArray(roles) ? roles : []).forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) roleMap.set(workshopRoleKey(normalized), normalized);
    });
    const normalizedRoles = [...roleMap.values()].filter(role => !MISTAKEN_CUSTOM_ROLE_NAMES.includes(role.name));
    try { hostWindow.localStorage.setItem(CUSTOM_ROLE_STORAGE_KEY, JSON.stringify(normalizedRoles)); } catch (_) {}
    queueDialogueCustomRoleAvatarRegexSync('workshop-save-custom-roles');
    notifyStatusbarExternalRoles();
    broadcastCustomRoleSync('workshop-save-custom-roles');
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    return normalizedRoles;
  }

  function isManualRoleWorldbookEntry(entry, roleName) {
    const name = asCleanText(roleName, 40);
    const source = String(entry?.extra?.source || '');
    if (source === SOURCE_TAG) return false;
    const sourceName = asCleanText(entry?.extra?.custom_role_name || '', 40);
    const entryName = asCleanText(entry?.name || entry?.comment || '', 40);
    const keys = Array.isArray(entry?.keys) ? entry.keys.map(value => asCleanText(value, 80)).filter(Boolean) : [];
    if (source === STATUS_ROLE_SOURCE) return sourceName === name || entryName === name;
    if (source) return false;
    return entryName === '自定义NPC_' + name || (entryName === name && keys.length === 1 && keys[0] === name);
  }

  async function migrateLegacySharedWorkshopRoles() {
    const getNames = getHelperFunction('getWorldbookNames');
    const getWorldbook = getHelperFunction('getWorldbook');
    if (typeof getNames !== 'function' || typeof getWorldbook !== 'function') return false;
    const names = await getNames();
    if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) return false;
    const worldbook = await getWorldbook(WORLDBOOK_NAME);
    const entries = Array.isArray(worldbook) ? worldbook : [];
    const workshopEntries = entries.filter(entry => entry?.extra?.source === SOURCE_TAG && entry?.extra?.custom_role);
    if (!workshopEntries.length) return false;
    let legacyRoles = [];
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(STATUS_ROLE_STORAGE_KEY) || '[]');
      if (Array.isArray(parsed)) legacyRoles = parsed;
    } catch (_) {}
    if (!legacyRoles.length) return false;
    const legacyByName = new Map();
    legacyRoles.forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) legacyByName.set(normalized.name, role);
    });
    const workshopRoles = loadCustomRoles();
    const existingKeys = new Set(workshopRoles.map(workshopRoleKey));
    const movedNames = new Set();
    let added = 0;
    workshopEntries.forEach(entry => {
      const roleName = asCleanText(entry?.extra?.custom_role_name || entry?.name || entry?.comment || '', 40);
      const legacyRole = legacyByName.get(roleName);
      if (!legacyRole) return;
      const migrated = normalizeCustomRole({
        ...legacyRole,
        moduleId: String(entry?.extra?.module_id || ''),
        entryId: String(entry?.extra?.workshop_entry_id || entry?.uid || roleName),
      });
      if (!migrated) return;
      const identity = workshopRoleKey(migrated);
      if (!existingKeys.has(identity)) {
        existingKeys.add(identity);
        workshopRoles.push(migrated);
        added += 1;
      }
      if (!entries.some(candidate => isManualRoleWorldbookEntry(candidate, roleName))) movedNames.add(roleName);
    });
    if (added > 0) saveCustomRoles(workshopRoles);
    if (movedNames.size > 0) {
      const keptLegacyRoles = legacyRoles.filter(role => !movedNames.has(asCleanText(role?.name, 40)));
      try { hostWindow.localStorage.setItem(STATUS_ROLE_STORAGE_KEY, JSON.stringify(keptLegacyRoles)); } catch (_) {}
      notifyStatusbarExternalRoles();
    }
    return added > 0 || movedNames.size > 0;
  }

  function loadUserAvatarUrl() {
    try { return normalizePlayerAvatarValue(hostWindow.localStorage.getItem(USER_AVATAR_STORAGE_KEY) || ''); } catch (_) { return ''; }
  }

  function getDefaultNpcRecord(role) {
    return {
      宗门: role?.sect || '自定义',
      境界: '未知',
      当前所在地: '未知',
      好感度数值: 0,
      好感度阶段: '形同陌路',
      关系标签: '初识',
      新增互动输入: '',
      最近互动记录: ['暂无'],
    };
  }

  function mergeNpcRecord(existing, role) {
    return { ...getDefaultNpcRecord(role), ...(isPlainObject(existing) ? existing : {}) };
  }

  function broadcastCustomRoleSync(reason = 'workshop') {
    const detail = { reason, roles: getEffectiveCustomRoles(), userAvatar: loadUserAvatarUrl() };
    try { hostWindow.dispatchEvent(new CustomEvent(CUSTOM_ROLE_SYNC_EVENT, { detail })); } catch (_) {}
    try { window.dispatchEvent(new CustomEvent(CUSTOM_ROLE_SYNC_EVENT, { detail })); } catch (_) {}
  }

  function buildCustomRolePromptText(roles = getEffectiveCustomRoles()) {
    if (!roles.length) return '';
    const lines = roles.map(role => `- ${role.name}（${role.sect || '自定义'}）：创意工坊自定义主要 NPC；可写入 /人际交往/结识道友录 与 /人际交往/当前接触人物；不得降级写入 /人际交往/路遇道友录。`);
    return ['创意工坊自定义主要 NPC 白名单：'].concat(lines).join('\n');
  }

  function injectCustomRolePrompt() {
    const content = buildCustomRolePromptText();
    const uninject = getHelperFunction('uninjectPrompts');
    try { if (typeof uninject === 'function') uninject([CUSTOM_ROLE_PROMPT_ID]); } catch (_) {}
    if (!content) return false;
    const inject = getHelperFunction('injectPrompts');
    if (typeof inject !== 'function') return false;
    try {
      inject([{ id: CUSTOM_ROLE_PROMPT_ID, position: 'in_chat', depth: 0, role: 'system', content, should_scan: false }]);
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色白名单注入失败', error);
      return false;
    }
  }

  function syncCustomRolesToChatVariables() {
    const updateVars = getHelperFunction('updateVariablesWith');
    if (typeof updateVars !== 'function') return false;
    try {
      updateVars(variables => {
        const next = variables && typeof variables === 'object' ? variables : {};
        next[CUSTOM_ROLE_CHAT_VAR] = {
          roles: getEffectiveCustomRoles().map(role => ({
            name: role.name,
            sect: role.sect || '自定义',
            avatar: role.defaultImg,
            portrait: role.portraitImg || role.defaultImg,
            profile: role.profile || '',
          })),
          userAvatar: loadUserAvatarUrl(),
          updatedAt: Date.now(),
        };
        return next;
      }, { type: 'chat' });
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色聊天变量同步失败', error);
      return false;
    }
  }

  async function syncCustomRoleToLatestMvu(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
    try {
      const data = mvuObj.getMvuData({ type: 'message', message_id: -1 });
      if (!data || typeof data !== 'object') return false;
      if (!isPlainObject(data.stat_data)) data.stat_data = {};
      if (!isPlainObject(data.stat_data.人际交往)) data.stat_data.人际交往 = {};
      if (!isPlainObject(data.stat_data.人际交往.结识道友录)) data.stat_data.人际交往.结识道友录 = {};
      data.stat_data.人际交往.结识道友录[normalized.name] = mergeNpcRecord(data.stat_data.人际交往.结识道友录[normalized.name], normalized);
      if (isPlainObject(data.stat_data.人际交往.路遇道友录) && Object.prototype.hasOwnProperty.call(data.stat_data.人际交往.路遇道友录, normalized.name)) {
        delete data.stat_data.人际交往.路遇道友录[normalized.name];
      }
      await mvuObj.replaceMvuData(data, { type: 'message', message_id: -1 });
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入最新 MVU 变量失败', error);
      return false;
    }
  }

  function upsertNameInJsStringArray(content, constName, roleName) {
    const cleanName = asCleanText(roleName, 40);
    if (!cleanName || typeof content !== 'string') return content;
    const pattern = new RegExp('(const\\s+' + constName + '\\s*=\\s*\\[)([\\s\\S]*?)(\\n\\s*\\];)');
    return content.replace(pattern, (full, head, body, tail) => {
      const names = [...body.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"/g)]
        .map(match => {
          try { return JSON.parse(`"${match[1]}"`); } catch (_) { return match[1]; }
        })
        .filter(Boolean);
      if (names.includes(cleanName)) return full;
      names.push(cleanName);
      return `${head}\n${names.map(name => `    ${JSON.stringify(name)},`).join('\n')}${tail}`;
    });
  }

  async function syncCustomRoleToVariableSchema(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const updateScripts = getHelperFunction('updateScriptTreesWith');
    if (typeof updateScripts !== 'function') return false;
    let touched = false;
    const visit = trees => (Array.isArray(trees) ? trees : []).map(tree => {
      if (tree && tree.type === 'folder' && Array.isArray(tree.scripts)) return { ...tree, scripts: visit(tree.scripts) };
      if (!tree || tree.type !== 'script' || typeof tree.content !== 'string' || tree.name !== VARIABLE_SCHEMA_SCRIPT_NAME) return tree;
      const nextContent = upsertNameInJsStringArray(tree.content, 'MAIN_NPC_NAMES', normalized.name);
      if (nextContent !== tree.content) {
        touched = true;
        return { ...tree, content: nextContent };
      }
      return tree;
    });
    try {
      await updateScripts(trees => visit(trees), { type: 'character' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入 MAIN_NPC_NAMES 失败', error);
      return false;
    }
  }

  function upsertRoleNameInVariableRuleContent(content, roleName) {
    const cleanName = asCleanText(roleName, 40);
    if (!cleanName || typeof content !== 'string') return content;
    const appendName = namesText => {
      const names = String(namesText || '').split('、').map(name => name.trim()).filter(Boolean);
      if (!names.includes(cleanName)) names.push(cleanName);
      return names.join('、');
    };
    let next = content;
    next = next.replace(/(- 主要 NPC 名单：)([^；\n]*)(；[^\n]*)?/, (full, head, namesText, tail = '；状态栏或创意工坊保存的自定义角色也按主要 NPC 处理') => {
      return `${head}${appendName(namesText)}${tail}`;
    });
    next = next.replace(/(#### 白名单 NPC\s*\n)([\s\S]*?)(\n\n#### 更新规则)/, (full, head, body, tail) => {
      const exists = body.split(/\r?\n/).some(line => line.trim() === `- ${cleanName}`);
      if (exists) return full;
      return `${head}${body.trimEnd()}\n- ${cleanName}${tail}`;
    });
    next = next.replace(/(- 主要 NPC 仅允许写入 \/人际交往\/结识道友录：)([^；\n]*)(；以及(?:状态栏“角色图像”页|创意工坊)保存的自定义角色。)/, (full, head, namesText) => {
      return `${head}${appendName(namesText)}；以及创意工坊保存的自定义角色。`;
    });
    return next;
  }

  async function syncCustomRoleToWorldbookRules(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const updateWorldbook = getHelperFunction('updateWorldbookWith');
    if (typeof updateWorldbook !== 'function') return false;
    let touched = false;
    try {
      await updateWorldbook(WORLDBOOK_NAME, worldbook => (Array.isArray(worldbook) ? worldbook : []).map(entry => {
        const content = String(entry?.content || '');
        const entryName = entry?.name || entry?.comment || '';
        const isTarget = entryName === VARIABLE_UPDATE_RULE_ENTRY_NAME
          || (content.includes('变量更新规则:') && content.includes('当前接触人物:') && content.includes('主要 NPC 名单'))
          || (content.includes('### 3.3 当前接触人物') && content.includes('#### 白名单 NPC') && content.includes('#### 3.4 道友收录白名单与分流规则'));
        if (!isTarget) return entry;
        const nextContent = upsertRoleNameInVariableRuleContent(content, normalized.name);
        if (nextContent !== content) {
          touched = true;
          return { ...entry, content: nextContent };
        }
        return entry;
      }), { render: 'debounced' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入变量更新规则失败', error);
      return false;
    }
  }

  function removeNameFromJsStringArray(content, constName, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || typeof content !== 'string') return content;
    const pattern = new RegExp('(const\\s+' + constName + '\\s*=\\s*\\[)([\\s\\S]*?)(\\n\\s*\\];)');
    return content.replace(pattern, (full, head, body, tail) => {
      const names = [...body.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"/g)]
        .map(match => {
          try { return JSON.parse(`"${match[1]}"`); } catch (_) { return match[1]; }
        })
        .filter(name => name && !namesToRemove.has(name));
      return `${head}\n${names.map(name => `    ${JSON.stringify(name)},`).join('\n')}${tail}`;
    });
  }

  async function removeCustomRolesFromVariableSchema(roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean);
    if (!names.length) return false;
    const updateScripts = getHelperFunction('updateScriptTreesWith');
    if (typeof updateScripts !== 'function') return false;
    let touched = false;
    const visit = trees => (Array.isArray(trees) ? trees : []).map(tree => {
      if (tree && tree.type === 'folder' && Array.isArray(tree.scripts)) return { ...tree, scripts: visit(tree.scripts) };
      if (!tree || tree.type !== 'script' || typeof tree.content !== 'string' || tree.name !== VARIABLE_SCHEMA_SCRIPT_NAME) return tree;
      const nextContent = removeNameFromJsStringArray(tree.content, 'MAIN_NPC_NAMES', names);
      if (nextContent !== tree.content) {
        touched = true;
        return { ...tree, content: nextContent };
      }
      return tree;
    });
    try {
      await updateScripts(trees => visit(trees), { type: 'character' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色移除 MAIN_NPC_NAMES 失败', error);
      return false;
    }
  }

  function removeRoleNamesInVariableRuleContent(content, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || typeof content !== 'string') return content;
    let next = content;
    next = next.replace(/(#### 白名单 NPC\s*\n)([\s\S]*?)(\n\n#### 更新规则)/, (full, head, body, tail) => {
      const lines = body.split(/\r?\n/).filter(line => {
        const item = line.trim().replace(/^-\s*/, '');
        return !namesToRemove.has(item);
      });
      return `${head}${lines.join('\n').trimEnd()}${tail}`;
    });
    next = next.replace(/(- 主要 NPC 仅允许写入 \/人际交往\/结识道友录：)([^；\n]*)(；以及(?:状态栏“角色图像”页|创意工坊)保存的自定义角色。)/, (full, head, namesText, tail) => {
      const names = namesText.split('、').map(name => name.trim()).filter(name => name && !namesToRemove.has(name));
      return `${head}${names.join('、')}${tail}`;
    });
    return next;
  }

  async function removeCustomRolesFromWorldbookRules(roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean);
    if (!names.length) return false;
    const updateWorldbook = getHelperFunction('updateWorldbookWith');
    if (typeof updateWorldbook !== 'function') return false;
    let touched = false;
    try {
      await updateWorldbook(WORLDBOOK_NAME, worldbook => (Array.isArray(worldbook) ? worldbook : []).map(entry => {
        const content = String(entry?.content || '');
        const entryName = entry?.name || entry?.comment || '';
        const isTarget = entryName === VARIABLE_UPDATE_RULE_ENTRY_NAME
          || (content.includes('### 3.3 当前接触人物') && content.includes('#### 白名单 NPC') && content.includes('#### 3.4 道友收录白名单与分流规则'));
        if (!isTarget) return entry;
        const nextContent = removeRoleNamesInVariableRuleContent(content, names);
        if (nextContent !== content) {
          touched = true;
          return { ...entry, content: nextContent };
        }
        return entry;
      }), { render: 'debounced' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色移出变量更新规则失败', error);
      return false;
    }
  }

  function removeRoleNamesFromRelationState(data, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || !data || typeof data !== 'object') return false;
    const relation = data.stat_data?.人际交往 || data.人际交往;
    if (!isPlainObject(relation)) return false;
    let touched = false;
    ['结识道友录', '当前接触人物', '路遇道友录'].forEach(key => {
      if (!isPlainObject(relation[key])) return;
      namesToRemove.forEach(name => {
        if (Object.prototype.hasOwnProperty.call(relation[key], name)) {
          delete relation[key][name];
          touched = true;
        }
      });
    });
    return touched;
  }

  async function removeCustomRolesFromMvuMessages(roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean);
    if (!names.length) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
    const ids = [-1, 'latest'];
    try {
      const currentId = getHelperFunction('getCurrentMessageId')?.();
      const lastId = getHelperFunction('getLastMessageId')?.();
      [currentId, lastId].forEach(id => {
        if (id !== null && id !== undefined && id !== '') ids.push(id);
      });
    } catch (_) {}
    let touchedAny = false;
    for (const id of [...new Set(ids.map(id => String(id)))]) {
      const messageId = id === '-1' ? -1 : id;
      try {
        const data = mvuObj.getMvuData({ type: 'message', message_id: messageId });
        if (!data || typeof data !== 'object') continue;
        if (!removeRoleNamesFromRelationState(data, names)) continue;
        await mvuObj.replaceMvuData(data, { type: 'message', message_id: messageId });
        touchedAny = true;
      } catch (_) {}
    }
    return touchedAny;
  }

  function removeCustomRolesFromChatVariables(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    const updateVars = getHelperFunction('updateVariablesWith');
    if (typeof updateVars !== 'function') return false;
    try {
      updateVars(variables => {
        const next = variables && typeof variables === 'object' ? variables : {};
        const payload = next[CUSTOM_ROLE_CHAT_VAR];
        if (payload && typeof payload === 'object') {
          payload.roles = Array.isArray(payload.roles)
            ? payload.roles.filter(role => !namesToRemove.has(asCleanText(role?.name || role?.label, 40)))
            : [];
          payload.updatedAt = Date.now();
        }
        return next;
      }, { type: 'chat' });
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色聊天变量清理失败', error);
      return false;
    }
  }

  function removeCustomRolesFromLocalCaches(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    let touched = false;
    try {
      const raw = hostWindow.localStorage.getItem(CUSTOM_ROLE_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      if (Array.isArray(parsed)) {
        const kept = parsed.filter(role => !namesToRemove.has(asCleanText(role?.name || role?.label, 40)));
        if (kept.length !== parsed.length) {
          hostWindow.localStorage.setItem(CUSTOM_ROLE_STORAGE_KEY, JSON.stringify(kept));
          touched = true;
        }
      }
    } catch (_) {}
    ['mvu_npc_order'].forEach(key => {
      try {
        const parsed = JSON.parse(hostWindow.localStorage.getItem(key) || '[]');
        if (!Array.isArray(parsed)) return;
        const kept = parsed.filter(name => !namesToRemove.has(asCleanText(name, 40)));
        if (kept.length !== parsed.length) {
          hostWindow.localStorage.setItem(key, JSON.stringify(kept));
          touched = true;
        }
      } catch (_) {}
    });
    try {
      const records = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_records') || '{}');
      if (isPlainObject(records)) {
        namesToRemove.forEach(name => {
          if (Object.prototype.hasOwnProperty.call(records, name)) {
            delete records[name];
            touched = true;
          }
        });
        hostWindow.localStorage.setItem('mvu_npc_records', JSON.stringify(records));
      }
    } catch (_) {}
    try {
      const cache = JSON.parse(hostWindow.localStorage.getItem('mvu_new_badge_cache') || '{}');
      if (isPlainObject(cache)) {
        ['daoist', 'minorDaoist'].forEach(category => {
          if (!isPlainObject(cache[category])) return;
          namesToRemove.forEach(name => {
            if (Object.prototype.hasOwnProperty.call(cache[category], name)) {
              delete cache[category][name];
              touched = true;
            }
          });
        });
        hostWindow.localStorage.setItem('mvu_new_badge_cache', JSON.stringify(cache));
      }
    } catch (_) {}
    return touched;
  }

  async function removeCustomRolesFromStatusbarApi() {
    const api = getStatusbarRoleApi();
    if (!api || typeof api.syncExternal !== 'function') return false;
    try {
      await api.syncExternal();
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 状态栏外部角色刷新失败', error);
      return false;
    }
  }

  async function removeCustomRolesFromLatestMvu(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
    try {
      return await removeCustomRolesFromMvuMessages([...namesToRemove]);
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色移出最新 MVU 变量失败', error);
      return false;
    }
  }

  function removeCustomRolesFromLocalOrder(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    try {
      const order = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_order') || '[]');
      if (!Array.isArray(order)) return false;
      const nextOrder = order.filter(name => !namesToRemove.has(String(name || '')));
      if (nextOrder.length === order.length) return false;
      hostWindow.localStorage.setItem('mvu_npc_order', JSON.stringify(nextOrder));
      return true;
    } catch (_) {
      return false;
    }
  }

  async function removeCustomRolesByNames(roleNames) {
    const names = [...new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean))];
    if (!names.length) return { removed: 0, names: [] };
    const nameSet = new Set(names);
    const roles = loadCustomRoles();
    const keptRoles = roles.filter(role => !nameSet.has(role.name));
    const removed = roles.length - keptRoles.length;
    if (removed > 0) saveCustomRoles(keptRoles);
    const remainingWorkshopNames = new Set(getEffectiveCustomRoles(keptRoles).map(role => role.name));
    const manualNames = new Set(loadStatusbarManualRoles().map(role => role.name));
    const cleanupNames = names.filter(name => !remainingWorkshopNames.has(name) && !manualNames.has(name));
    const results = {
      removed,
      names,
      cleanupNames,
      order: removeCustomRolesFromLocalOrder(cleanupNames),
      localCaches: removeCustomRolesFromLocalCaches(cleanupNames),
      chatVariables: removeCustomRolesFromChatVariables(cleanupNames),
      statusbar: await removeCustomRolesFromStatusbarApi(),
      latestMvu: await removeCustomRolesFromLatestMvu(cleanupNames),
      variableSchema: await removeCustomRolesFromVariableSchema(cleanupNames),
      variableRules: await removeCustomRolesFromWorldbookRules(cleanupNames),
    };
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    broadcastCustomRoleSync('workshop-remove-custom-role');
    return results;
  }

  function makeCustomNpcTag(roleName) {
    const encoded = Array.from(String(roleName || 'custom')).map(char => char.codePointAt(0).toString(16)).join('_');
    return `npc_custom_${encoded || 'role'}`;
  }

  function makePromptTagName(value) {
    const text = String(value || 'workshop_entry')
      .replace(/[<>\s\/"'`=]+/g, '_')
      .replace(/^_+|_+$/g, '')
      .slice(0, 80);
    return text || 'workshop_entry';
  }

  function hasOuterPromptTag(text) {
    const body = String(text || '').trim();
    const match = body.match(/^<([^>\s/]+)>[\s\S]*<\/\1>\s*$/);
    return !!match;
  }

  function wrapWorldbookBody(label, body) {
    const clean = asWorldbookBody(body);
    if (!clean) return '';
    if (hasOuterPromptTag(clean)) return clean;
    const tag = makePromptTagName(label);
    return `<${tag}>\n${clean}\n</${tag}>`;
  }

  function buildCustomRoleWorldbookContent(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return '';
    return wrapWorldbookBody(normalized.name, normalized.profile || `${normalized.name}:`);
  }

  function isCustomRoleWorldbookEntry(entry, roleName) {
    const cleanName = asCleanText(roleName, 40);
    const entryName = String(entry?.name || entry?.comment || '').trim();
    const content = String(entry?.content || '');
    return entryName === cleanName
      || entryName === `自定义NPC_${cleanName}`
      || content.includes(`姓名: ${cleanName}`)
      || content.includes(`<${makeCustomNpcTag(cleanName)}>`);
  }

  function buildCustomRoleWorldbookEntry(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return null;
    const keys = [normalized.name].filter(Boolean);
    return {
      type: 'selective',
      name: normalized.name,
      comment: normalized.name,
      enabled: true,
      strategy: {
        type: 'selective',
        keys,
        keys_secondary: { logic: 'and_any', keys: [] },
        scan_depth: 'same_as_global',
      },
      keys,
      secondary_keys: [],
      logic: 'and_any',
      filters: [],
      constant: false,
      selective: true,
      position: { type: 'before_character_definition', role: 'system', depth: 4, order: 100 },
      content: buildCustomRoleWorldbookContent(normalized),
      use_regex: true,
      insertion_order: 100,
      probability: 100,
      recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
      effect: { sticky: null, cooldown: null, delay: null },
      extensions: {
        position: 0,
        exclude_recursion: true,
        probability: 100,
        useProbability: true,
        depth: 4,
        selectiveLogic: 0,
        outlet_name: '',
        group: '',
        group_override: false,
        group_weight: 100,
        prevent_recursion: true,
        delay_until_recursion: false,
        scan_depth: null,
        match_whole_words: null,
        use_group_scoring: false,
        case_sensitive: null,
        automation_id: '',
        role: 0,
        vectorized: false,
        sticky: null,
        cooldown: null,
        delay: null,
        match_persona_description: false,
        match_character_description: false,
        match_character_personality: false,
        match_character_depth_prompt: false,
        match_scenario: false,
        match_creator_notes: false,
        triggers: [],
        ignore_budget: false,
      },
      extra: { source: SOURCE_TAG, kind: 'npc', custom_role: true },
    };
  }

  async function upsertCustomRoleWorldbookEntry(role) {
    const normalized = normalizeCustomRole(role);
    const entryPayload = buildCustomRoleWorldbookEntry(normalized);
    if (!normalized || !entryPayload) return false;
    await ensureWorldbook();
    const updateWorldbook = getHelperFunction('updateWorldbookWith');
    const createEntries = getHelperFunction('createWorldbookEntries');
    if (typeof updateWorldbook !== 'function') return false;
    let existed = false;
    try {
      await updateWorldbook(WORLDBOOK_NAME, worldbook => (Array.isArray(worldbook) ? worldbook : []).map(entry => {
        if (!isCustomRoleWorldbookEntry(entry, normalized.name)) return entry;
        existed = true;
        return { ...entry, ...entryPayload, uid: entry.uid };
      }), { render: 'debounced' });
      if (!existed && typeof createEntries === 'function') {
        await createEntries(WORLDBOOK_NAME, [entryPayload], { render: 'debounced' });
      }
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色世界书条目写入失败', error);
      return false;
    }
  }

  function getStatusbarRoleApi() {
    if (hostWindow.CangXuanStatusbarRoles) return hostWindow.CangXuanStatusbarRoles;
    try {
      const frame = hostDocument.getElementById('cx-floating-status-frame');
      if (frame?.contentWindow?.CangXuanStatusbarRoles) return frame.contentWindow.CangXuanStatusbarRoles;
    } catch (_) {}
    return null;
  }

  async function syncWorkshopCustomRole(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return { ok: false, reason: 'invalid' };
    const identity = workshopRoleKey(normalized);
    const roles = loadCustomRoles().filter(item => workshopRoleKey(item) !== identity);
    roles.push(normalized);
    saveCustomRoles(roles);
    try {
      let savedOrder = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_order') || '[]');
      if (!Array.isArray(savedOrder)) savedOrder = [];
      savedOrder = savedOrder.filter(name => name !== normalized.name);
      savedOrder.unshift(normalized.name);
      hostWindow.localStorage.setItem('mvu_npc_order', JSON.stringify(savedOrder));
    } catch (_) {}

    const results = {
      latestMvu: await syncCustomRoleToLatestMvu(normalized),
      variableSchema: await syncCustomRoleToVariableSchema(normalized),
      variableRules: await syncCustomRoleToWorldbookRules(normalized),
    };
    notifyStatusbarExternalRoles();
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    broadcastCustomRoleSync('workshop-custom-role');
    return { ok: true, role: normalized, via: 'workshop', results };
  }

  function extractCustomRolesFromModule(moduleInfo) {
    const entries = Array.isArray(moduleInfo?.content?.entries) ? moduleInfo.content.entries : [];
    const roles = [];
    for (const entry of entries) {
      const entryKind = String(entry?.kind || moduleInfo?.kind || '');
      if (entryKind !== 'npc') continue;
      const entryTitle = entry?.label || entry?.name || moduleInfo?.title;
      const entryBody = entryWorldbookText(entry || {}, moduleInfo || {}, null, entryTitle);
      const rawRole = entry?.customRole || entry?.custom_role || null;
      const fallback = {
        name: entryTitle,
        sect: entry?.sect || entry?.group || moduleInfo?.authorName || '自定义',
        profile: entryBody || entry?.profile || entry?.description || moduleInfo?.description || '',
        avatar: entry?.avatar || entry?.avatarUrl || entry?.avatar_url || entry?.defaultImg || entry?.default_img || entry?.imageUrl || entry?.image_url || entry?.image || entry?.icon || moduleInfo?.previewUrl,
        portrait: entry?.portrait || entry?.portraitUrl || entry?.portrait_url || entry?.portraitImg || entry?.portrait_img || entry?.coverUrl || entry?.cover_url || moduleInfo?.previewUrl,
      };
      const roleSource = isPlainObject(rawRole)
        ? { ...rawRole, profile: entryBody || rawRole.profile || rawRole.lore || rawRole.setting || rawRole.description || '' }
        : fallback;
      const normalized = normalizeCustomRole({
        ...roleSource,
        moduleId: String(moduleInfo?.id || ''),
        entryId: String(entry?.id || entryTitle || ''),
      });
      if (normalized) roles.push(normalized);
    }
    return roles;
  }

  async function syncCustomRolesFromModule(moduleInfo) {
    const roles = extractCustomRolesFromModule(moduleInfo);
    const results = [];
    for (const role of roles) results.push(await syncWorkshopCustomRole(role));
    return results;
  }

  function splitEntryList(value) {
    if (Array.isArray(value)) return value.map(item => String(item || '').trim()).filter(Boolean);
    if (typeof value === 'string') return value.split(/[\n,，、；;]+/).map(item => item.trim()).filter(Boolean);
    return [];
  }

  function firstTextValue(values) {
    for (const value of values) {
      if (typeof value !== 'string') continue;
      const clean = asWorldbookBody(value);
      if (clean) return clean;
    }
    return '';
  }

  function entryPrimaryKeys(entry, moduleInfo, customRole, title) {
    const keys = [
      ...splitEntryList(entry.keys),
      ...splitEntryList(entry.key),
      ...splitEntryList(entry.primary_keys),
      ...splitEntryList(entry.primaryKeys),
      ...splitEntryList(entry.keywords),
      ...splitEntryList(entry.keyword),
      ...splitEntryList(entry.triggers),
      ...splitEntryList(entry.triggerKeys),
      ...splitEntryList(entry.trigger_keys),
      ...splitEntryList(entry.promptKeys),
      ...splitEntryList(entry.prompt_keys),
      ...splitEntryList(entry.activationKeys),
      ...splitEntryList(entry.activation_keys),
      ...splitEntryList(entry.worldbookKeys),
      ...splitEntryList(entry.worldbook_keys),
    ];
    if (!keys.length && customRole?.name) keys.push(customRole.name);
    if (!keys.length && title) keys.push(title);
    if (!keys.length && moduleInfo?.title) keys.push(moduleInfo.title);
    return [...new Set(keys.map(item => asCleanText(item, 80)).filter(Boolean))];
  }

  function entrySecondaryKeys(entry) {
    const rawSecondary = entry.keys_secondary || entry.keysecondary || entry.keysSecondary || entry.secondary_keys || entry.secondaryKeys || {};
    const keys = [
      ...splitEntryList(rawSecondary.keys),
      ...splitEntryList(rawSecondary.key),
      ...splitEntryList(rawSecondary),
      ...splitEntryList(entry.secondary),
      ...splitEntryList(entry.secondary_keys),
      ...splitEntryList(entry.secondaryKeys),
    ];
    return [...new Set(keys.map(item => asCleanText(item, 80)).filter(Boolean))];
  }

  function entrySecondaryLogic(entry) {
    const rawSecondary = entry.keys_secondary || entry.keysecondary || entry.keysSecondary || {};
    const logic = rawSecondary.logic || entry.secondaryLogic || entry.secondary_logic || entry.logic || 'and_any';
    return ['and_any', 'and_all', 'not_all', 'not_any'].includes(logic) ? logic : 'and_any';
  }

  function entryWorldbookText(entry, moduleInfo, customRole, title) {
    return firstTextValue([
      entry.yamlText,
      entry.yaml_text,
      entry.yaml,
      entry.prompt,
      entry.promptText,
      entry.prompt_text,
      entry.content,
      entry.body,
      entry.worldbook,
      entry.text,
      entry.lore,
      entry.setting,
      entry.description,
      customRole?.profile,
      entry.profile,
      moduleInfo?.description,
      title ? `${title}:` : '',
    ]);
  }

  async function apiFetch(path, options = {}) {
    if (!isApiConfigured()) throw new Error('请先在“设置”里填写 Cloudflare Worker 地址');
    const response = await fetch(`${getApiBase()}${path}`, {
      cache: 'no-store',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(options.headers || {}),
      },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || `请求失败：HTTP ${response.status}`);
    return data;
  }

  async function loadModules(force) {
    if (state.modules && !force) return state.modules;
    const data = await apiFetch('/api/cultivation-world/modules?page_size=100');
    state.modules = Array.isArray(data.modules) ? data.modules : [];
    return state.modules;
  }

  async function downloadModule(moduleId) {
    const data = await apiFetch(`/api/cultivation-world/modules/${encodeURIComponent(moduleId)}/download`);
    return data.module || data;
  }

  async function submitModule(submission) {
    return apiFetch('/api/cultivation-world/submissions', {
      method: 'POST',
      body: JSON.stringify(submission),
    });
  }

  function toWorldbookEntry(entry, moduleInfo) {
    const moduleId = String(moduleInfo.id || entry.sourceModuleId || '');
    const entryId = String(entry.id || `${moduleId}-entry`);
    const kind = String(entry.kind || moduleInfo.kind || 'region');
    const title = entry.label || entry.name || moduleInfo.title || `工坊条目 ${entryId}`;
    const rawCustomRole = entry.customRole || entry.custom_role || (kind === 'npc' ? {
      name: title,
      sect: entry.sect || entry.group || moduleInfo.authorName || '自定义',
      avatar: entry.avatar || entry.avatarUrl || entry.avatar_url || entry.defaultImg || entry.default_img || entry.imageUrl || entry.image_url || entry.image || entry.icon || moduleInfo.previewUrl,
      portrait: entry.portrait || entry.portraitUrl || entry.portrait_url || entry.portraitImg || entry.portrait_img || entry.coverUrl || entry.cover_url || moduleInfo.previewUrl,
      profile: entry.profile || entry.description || moduleInfo.description || '',
    } : null);
    const customRole = normalizeCustomRole(rawCustomRole);
    const isNpc = kind === 'npc' && !!customRole;
    const keys = entryPrimaryKeys(entry, moduleInfo, customRole, title);
    const secondaryKeys = entrySecondaryKeys(entry);
    const secondaryLogic = entrySecondaryLogic(entry);
    const bodyText = entryWorldbookText(entry, moduleInfo, customRole, title);
    return {
      name: title,
      comment: title,
      enabled: true,
      type: 'selective',
      strategy: {
        type: 'selective',
        keys,
        keys_secondary: {
          logic: secondaryLogic,
          keys: secondaryKeys,
        },
        scan_depth: 'same_as_global',
      },
      keys,
      secondary_keys: secondaryKeys,
      logic: secondaryLogic,
      filters: [],
      constant: false,
      selective: true,
      position: {
        type: 'before_character_definition',
        role: 'system',
        depth: 4,
        order: 100,
      },
      content: wrapWorldbookBody(title, bodyText),
      use_regex: true,
      insertion_order: 100,
      probability: 100,
